import pytest
import requests


def test_unauthorized_article_update_and_delete_vulnerability():
    """
    Test demonstrating security vulnerability where any authenticated user
    can update or delete articles they don't own.
    """
    base_url = "http://localhost:3000"

    # Create user1 (owner1)
    user1_data = {
        "user": {
            "username": "owner1",
            "email": "owner1@test.com",
            "password": "pass123"
        }
    }
    response = requests.post(f"{base_url}/api/users", json=user1_data)
    assert response.status_code in [200, 201]
    user1_token = response.json()["user"]["token"]
    assert user1_token is not None

    # Create user2 (attacker1)
    user2_data = {
        "user": {
            "username": "attacker1",
            "email": "attacker1@test.com",
            "password": "pass123"
        }
    }
    response = requests.post(f"{base_url}/api/users", json=user2_data)
    assert response.status_code in [200, 201]
    user2_token = response.json()["user"]["token"]
    assert user2_token is not None

    # User1 creates article with title 'Original Owner Article'
    article1_data = {
        "article": {
            "title": "Original Owner Article",
            "description": "Test article description",
            "body": "Test article body"
        }
    }
    headers_user1 = {"Authorization": f"Token {user1_token}"}
    response = requests.post(f"{base_url}/api/articles", json=article1_data, headers=headers_user1)
    assert response.status_code == 201
    article1_slug = response.json()["slug"]
    assert article1_slug is not None

    # Verify article exists
    response = requests.get(f"{base_url}/api/articles/{article1_slug}")
    assert response.status_code == 200
    assert response.json()["article"]["title"] == "Original Owner Article"

    # User2 (NOT the owner) PUTs /api/articles/{slug} with title 'Hacked By User2'
    update_data = {
        "article": {
            "title": "Hacked By User2"
        }
    }
    headers_user2 = {"Authorization": f"Token {user2_token}"}
    response = requests.put(f"{base_url}/api/articles/{article1_slug}", json=update_data, headers=headers_user2)

    # Verify PUT response shows updated title
    assert response.status_code == 200
    assert response.json()["article"]["title"] == "Hacked By User2"

    # GET article and verify title changed
    response = requests.get(f"{base_url}/api/articles/{article1_slug}")
    assert response.status_code == 200
    assert response.json()["article"]["title"] == "Hacked By User2"

    # User1 creates second article 'Article To Delete'
    article2_data = {
        "article": {
            "title": "Article To Delete",
            "description": "Article that will be deleted",
            "body": "This article will be deleted by user2"
        }
    }
    response = requests.post(f"{base_url}/api/articles", json=article2_data, headers=headers_user1)
    assert response.status_code == 201
    article2_slug = response.json()["slug"]
    assert article2_slug is not None

    # User2 (NOT the owner) DELETEs /api/articles/{slug}
    response = requests.delete(f"{base_url}/api/articles/{article2_slug}", headers=headers_user2)

    # Verify DELETE succeeds with status 200
    assert response.status_code == 200

    # GET the deleted article and verify it returns 200 with empty object {}
    response = requests.get(f"{base_url}/api/articles/{article2_slug}")
    assert response.status_code == 200
    assert response.json() == {}

import pytest
import requests
import json

@pytest.fixture
def base_url():
    return "http://localhost:8000"

def test_create_item_validation_error(base_url):
    # Register a new user
    response = requests.post(
        f"{base_url}/api/v1/users/signup",
        json={
            "email": "test55@example.com",
            "password": "validpass123",
        }
    )
    assert response.status_code == 200

    # Login to get token
    response = requests.post(
        f"{base_url}/api/v1/login/access-token",
        data={
            "grant_type": "password",
            "username": "test55@example.com",
            "password": "validpass123",
        }
    )
    assert response.status_code == 200
    token = response.json()["access_token"]

    # Create item with invalid description length
    response = requests.post(
        f"{base_url}/api/v1/items/",
        json={
            "title": "Valid Title",
            "description": "a" * 256,
        },
        headers={"Authorization": f"Bearer {token}"}
    )
    assert response.status_code == 422
    assert "detail" in response.json()
    assert len(response.json()["detail"]) > 0
    error_msg = response.json()["detail"][0]["msg"]
    assert "Ensure this field has no more than 255 characters" in error_msg or "String should have at most 255 characters" in error_msg

import pytest
import requests
import json

def test_create_user_and_article():
    # Create user
    api_url = "http://localhost:3000/api"
    user_data = {
        "user": {
            "username": "fieldsuser1",
            "email": "fieldsuser1@test.com",
            "password": "pass123"
        }
    }
    response = requests.post(f"{api_url}/users", json=user_data)
    assert response.status_code == 201
    assert response.json()["user"]["username"] == "fieldsuser1"
    assert response.json()["user"]["email"] == "fieldsuser1@test.com"

    # Login user
    login_data = {
        "user": {
            "email": "fieldsuser1@test.com",
            "password": "pass123"
        }
    }
    response = requests.post(f"{api_url}/users/login", json=login_data)
    assert response.status_code == 201
    token = response.json()["user"]["token"]

    # Create article
    article_data = {
        "article": {
            "title": "Test Article Title",
            "description": "Test article description content",
            "body": "This is the article body",
            "tagList": []
        }
    }
    response = requests.post(f"{api_url}/articles", json=article_data, headers={"Authorization": f"Token {token}"})
    assert response.status_code == 201
    slug = response.json()["slug"]
    assert response.json()["title"] == "Test Article Title"
    assert response.json()["description"] == "Test article description content"

    # Get article
    response = requests.get(f"{api_url}/articles/{slug}")
    assert response.status_code == 200
    assert response.json()["article"]["title"] == "Test Article Title"
    assert response.json()["article"]["description"] == "Test article description content"

def main():
    test_create_user_and_article()

if __name__ == "__main__":
    main()

import requests
import pytest

def test_admin_change_password_with_incorrect_current_and_new_rejected():
    base_url = "http://localhost:8000"

    # Step 1: Admin login to obtain access token
    login_url = f"{base_url}/api/v1/login/access-token"
    login_data = {
        "grant_type": "password",
        "username": "admin@example.com",
        "password": "password123"
    }

    login_resp = requests.post(login_url, data=login_data)
    assert login_resp.status_code == 200, f"Login failed with status {login_resp.status_code}: {login_resp.text}"

    try:
        token = login_resp.json().get("access_token")
    except ValueError:
        pytest.fail("Login response is not valid JSON")

    assert isinstance(token, str) and token, "Access token is missing or invalid"

    # Step 2: Attempt to update password using the same incorrect string for current and new passwords
    update_url = f"{base_url}/api/v1/users/me/password"
    payload = {
        "current_password": "incorrect-password",
        "new_password": "incorrect-password"
    }
    headers = {
        "Authorization": f"Bearer {token}"
    }

    update_resp = requests.patch(update_url, json=payload, headers=headers)

    # The operation should be rejected (current password is incorrect)
    assert update_resp.status_code == 400, (
        f"Expected 400 when current password is incorrect, got {update_resp.status_code}: {update_resp.text}"
    )

    # Validate error structure
    try:
        error_body = update_resp.json()
    except ValueError:
        pytest.fail("Error response is not valid JSON")

    # Prefer a detail field, but be flexible if the API uses a different key
    if "detail" in error_body:
        detail = error_body["detail"]
        assert isinstance(detail, str), f"'detail' should be a string, got {type(detail)}"
        assert detail, "Error detail should be a non-empty string"
    elif "message" in error_body:
        message = error_body["message"]
        assert isinstance(message, str), f"'message' should be a string, got {type(message)}"
        assert message, "Error message should be a non-empty string"
    else:
        pytest.fail("Error response does not contain 'detail' or 'message' field")

import pytest
import requests
import json

def test_profile_following_status():
    # Register two new users
    register_user1_response = requests.post(
        "http://localhost:3000/api/users",
        json={
            "user": {
                "username": "testuser1",
                "email": "testuser1@example.com",
                "password": "password123"
            }
        }
    )
    assert register_user1_response.status_code == 201
    register_user2_response = requests.post(
        "http://localhost:3000/api/users",
        json={
            "user": {
                "username": "testuser2",
                "email": "testuser2@example.com",
                "password": "password123"
            }
        }
    )
    assert register_user2_response.status_code == 201

    # Login as testuser1
    login_user1_response = requests.post(
        "http://localhost:3000/api/users/login",
        json={
            "user": {
                "email": "testuser1@example.com",
                "password": "password123"
            }
        }
    )
    assert login_user1_response.status_code == 200
    user1_token = login_user1_response.json()["user"]["token"]

    # Get testuser2's profile as testuser1 (not following)
    get_profile_response = requests.get(
        "http://localhost:3000/api/profiles/testuser2",
        headers={"Authorization": f"Token {user1_token}"}
    )
    assert get_profile_response.status_code == 200
    assert get_profile_response.json()["profile"]["following"] == False

    # Follow testuser2 as testuser1
    follow_user_response = requests.post(
        "http://localhost:3000/api/profiles/testuser2/follow",
        headers={"Authorization": f"Token {user1_token}"}
    )
    assert follow_user_response.status_code == 201

    # Get testuser2's profile as testuser1 (following)
    get_profile_response = requests.get(
        "http://localhost:3000/api/profiles/testuser2",
        headers={"Authorization": f"Token {user1_token}"}
    )
    assert get_profile_response.status_code == 200
    assert get_profile_response.json()["profile"]["following"] == True

    # Unfollow testuser2 as testuser1
    unfollow_user_response = requests.delete(
        "http://localhost:3000/api/profiles/testuser2/follow",
        headers={"Authorization": f"Token {user1_token}"}
    )
    assert unfollow_user_response.status_code == 200

    # Get testuser2's profile as testuser1 (not following)
    get_profile_response = requests.get(
        "http://localhost:3000/api/profiles/testuser2",
        headers={"Authorization": f"Token {user1_token}"}
    )
    assert get_profile_response.status_code == 200
    assert get_profile_response.json()["profile"]["following"] == False

import requests
import time

MAILCATCHER_URL = "http://localhost:1080/messages"
API_BASE = "http://localhost:8000"

def message_contains_email(msg, email):
    if not isinstance(msg, dict):
        return False

    target = email.lower()

    # Common fields that may contain recipient addresses
    for key in ("to", "to_email", "recipient", "recipients"):
        if key in msg:
            val = msg[key]
            if isinstance(val, list):
                for item in val:
                    if isinstance(item, str) and item.lower() == target:
                        return True
            elif isinstance(val, str) and val.lower() == target:
                return True

    # Some mailcatcher responses include headers with To
    headers = msg.get("headers")
    if isinstance(headers, dict):
        to_header = headers.get("To") or headers.get("to")
        if isinstance(to_header, str):
            # Could be "Name <email@example.com>, Other <other@example.com>"
            parts = [p.strip() for p in to_header.split(",")]
            for part in parts:
                if part.lower().endswith("<" + target + ">"):
                    return True
                if part.lower() == target:
                    return True

    return False

def test_signup_and_password_recovery_sends_email_and_mailcatcher_receives():
    # 1) Register a normal user
    signup_url = f"{API_BASE}/api/v1/users/signup"
    user_payload = {
        "email": "test15@example.com",
        "password": "TestPassword123!",
        "full_name": "Test User"
    }

    signup_resp = requests.post(signup_url, json=user_payload)
    assert signup_resp.status_code == 200, (
        f"Signup failed with status {signup_resp.status_code}: {signup_resp.text}"
    )

    try:
        signup_data = signup_resp.json()
    except ValueError:
        assert False, "Signup response is not valid JSON"

    assert isinstance(signup_data, dict), "Signup response should be a JSON object"
    assert "id" in signup_data, "Signup response missing 'id'"
    assert "email" in signup_data, "Signup response missing 'email'"
    assert signup_data["email"] == user_payload["email"]
    assert isinstance(signup_data.get("is_active"), bool), "'is_active' should be a boolean"

    # 2) Request a password recovery email
    recovery_url = f"{API_BASE}/api/v1/password-recovery/{user_payload['email']}"
    recovery_resp = requests.post(recovery_url)
    assert recovery_resp.status_code == 200, (
        f"Password recovery request failed with status {recovery_resp.status_code}: {recovery_resp.text}"
    )

    try:
        recovery_data = recovery_resp.json()
    except ValueError:
        assert False, "Password recovery response is not valid JSON"

    assert isinstance(recovery_data, dict), "Password recovery response should be a JSON object"
    assert "message" in recovery_data, "Password recovery response missing 'message'"
    assert recovery_data["message"] == "Password recovery email sent"

    # 3) Verify that an email was sent to the correct recipient via mailcatcher
    # Allow a short window for mail delivery
    email_found = False
    max_retries = 8
    delay_between_retries = 0.5  # seconds

    for _ in range(max_retries):
        try:
            mail_resp = requests.get(MAILCATCHER_URL, timeout=5)
            if mail_resp.status_code != 200:
                # Try again after a short delay
                time.sleep(delay_between_retries)
                continue

            try:
                mails = mail_resp.json()
            except ValueError:
                # If mailcatcher returns HTML or non-JSON, skip this attempt
                mails = None

            if isinstance(mails, list):
                for m in mails:
                    if message_contains_email(m, user_payload["email"]):
                        email_found = True
                        break
            elif isinstance(mails, dict):
                # Some mailcatcher versions return a dict with a 'messages' key
                messages = mails.get("messages") or mails.get("data")
                if isinstance(messages, list):
                    for m in messages:
                        if message_contains_email(m, user_payload["email"]):
                            email_found = True
                            break

            if email_found:
                break
        except Exception:
            # In case mailcatcher is temporarily unavailable, retry
            pass

        time.sleep(delay_between_retries)

    assert email_found, (
        f"No mailcatcher message found for recipient {user_payload['email']} after "
        f"{max_retries * delay_between_retries:.1f} seconds"
    )

import requests
import pytest

BASE_URL = "http://localhost:3000/api"


def test_user_creation_and_unique_constraints():
    headers = {"Content-Type": "application/json"}

    # 1) Create initial user (should succeed with 201)
    payload_create = {
        "user": {
            "username": "uniqueuser1",
            "email": "unique1@test.com",
            "password": "pass123"
        }
    }

    resp_create = requests.post(f"{BASE_URL}/users", json=payload_create, headers=headers)
    assert resp_create.status_code == 201, f"Expected status 201 for initial user creation, got {resp_create.status_code}. Body: {resp_create.text}"

    # Validate response JSON structure and exact values
    try:
        body_create = resp_create.json()
    except ValueError:
        pytest.fail(f"Response is not valid JSON for initial creation: {resp_create.text}")

    assert isinstance(body_create, dict), "Response JSON must be an object"
    assert "user" in body_create, "Response JSON must have top-level 'user' key"
    user_obj = body_create["user"]
    assert isinstance(user_obj, dict), "'user' must be an object"

    # Check required user fields and types
    for field in ("email", "username", "token", "bio", "image"):
        assert field in user_obj, f"Missing '{field}' in returned user object"
    assert user_obj["username"] == "uniqueuser1", f"Expected username 'uniqueuser1', got {user_obj['username']}"
    assert user_obj["email"] == "unique1@test.com", f"Expected email 'unique1@test.com', got {user_obj['email']}"
    assert isinstance(user_obj["token"], str) and user_obj["token"], "token must be a non-empty string"
    assert isinstance(user_obj["bio"], (str, type(None))) or isinstance(user_obj["bio"], str), "bio must be a string (or null)"
    assert isinstance(user_obj["image"], (str, type(None))) or isinstance(user_obj["image"], str), "image must be a string (or null)"

    # 2) Attempt to create another user with same username but different email -> expect 400 and specific error message
    payload_same_username = {
        "user": {
            "username": "uniqueuser1",
            "email": "different@test.com",
            "password": "pass123"
        }
    }
    resp_dup_username = requests.post(f"{BASE_URL}/users", json=payload_same_username, headers=headers)
    assert resp_dup_username.status_code == 400, (
        f"Expected status 400 when creating user with duplicate username, got {resp_dup_username.status_code}. Body: {resp_dup_username.text}"
    )

    # Validate error response contains the exact message
    try:
        body_dup_username = resp_dup_username.json()
    except ValueError:
        pytest.fail(f"Duplicate-username response is not valid JSON: {resp_dup_username.text}")

    assert isinstance(body_dup_username, dict), "Duplicate-username response JSON must be an object"
    assert "errors" in body_dup_username, "Duplicate-username response must contain 'errors' key"
    errors_obj = body_dup_username["errors"]
    assert isinstance(errors_obj, dict), "'errors' must be an object"
    assert "body" in errors_obj, "'errors' object must contain 'body' key"
    assert isinstance(errors_obj["body"], list), "'errors.body' must be a list"
    assert any("Username and email must be unique" in msg for msg in errors_obj["body"]), (
        f"Expected error message 'Username and email must be unique' in errors.body, got: {errors_obj['body']}"
    )

    # 3) Attempt to create another user with different username but same email -> expect 400 and same specific error message
    payload_same_email = {
        "user": {
            "username": "differentuser",
            "email": "unique1@test.com",
            "password": "pass123"
        }
    }
    resp_dup_email = requests.post(f"{BASE_URL}/users", json=payload_same_email, headers=headers)
    assert resp_dup_email.status_code == 400, (
        f"Expected status 400 when creating user with duplicate email, got {resp_dup_email.status_code}. Body: {resp_dup_email.text}"
    )

    try:
        body_dup_email = resp_dup_email.json()
    except ValueError:
        pytest.fail(f"Duplicate-email response is not valid JSON: {resp_dup_email.text}")

    assert isinstance(body_dup_email, dict), "Duplicate-email response JSON must be an object"
    assert "errors" in body_dup_email, "Duplicate-email response must contain 'errors' key"
    errors_obj2 = body_dup_email["errors"]
    assert isinstance(errors_obj2, dict), "'errors' must be an object"
    assert "body" in errors_obj2, "'errors' object must contain 'body' key"
    assert isinstance(errors_obj2["body"], list), "'errors.body' must be a list"
    assert any("Username and email must be unique" in msg for msg in errors_obj2["body"]), (
        f"Expected error message 'Username and email must be unique' in errors.body, got: {errors_obj2['body']}"
    )
